$faultIndex=250;foreach($faults as$phase=>$expectedReason){$faultIndex++;$fault=new InMemoryAssignmentOrderOriginalInitialEnvironment();$app=AssignmentOrderOriginalVerificationFactory::create($fault->dependencies());$mode=AssignmentOrderOriginalMode::INITIAL;$root=$target=null;if($phase==='lineage_lookup'){$reads=0;$accepted=$app->submitAssignmentOrderOriginal($command(sprintf('00000000-0000-4000-8000-%012d',900+$faultIndex),$mode,$stream($reads)));$fault->allowedCapability='assignment_order.original.correct';$mode=AssignmentOrderOriginalMode::CORRECTION;$root=$accepted->rootOriginalId();$target=$accepted->currentRevisionId();}$fault->throwAt=$phase;$reads=0;$caught=null;try{$result=$app->submitAssignmentOrderOriginal($command(sprintf('00000000-0000-4000-8000-%012d',$faultIndex),$mode,$stream($reads),'2026-09-01',$root,$target,$target,$mode===AssignmentOrderOriginalMode::CORRECTION?'reason':null));}catch(Throwable$e){$caught=$e;}assertSameValue(null,$caught,'Dependency Throwable is total at phase '.$phase);assertSameValue([AssignmentOrderOriginalStatus::FAILED,$expectedReason,true],[$result->status(),$result->reasonCode(),$result->retryable()],'Dependency Throwable has exact typed result at '.$phase);if(in_array($phase,['stage_write','stage_completed','inspector','fingerprint_lookup','stage_finalize'],true))assertSameValue(true,in_array('STAGE_CLOSE',$fault->storageEvents,true)&&in_array('ABORT_BEGIN',$fault->storageEvents,true),'Pre-finalize Throwable aborts and closes stage at '.$phase);if(in_array($phase,['root_id','revision_id','commit_accepted'],true))assertSameValue(1,$fault->leaseReleaseCalls,'Post-finalize Throwable releases lease exactly once at '.$phase);$public=json_encode([$rejected($result),$fault->safeLogs],JSON_THROW_ON_ERROR);assertSameValue(false,str_contains($public,$fault->throwSecret),'Unique dependency secret never leaks at '.$phase);}

$auditFault=new InMemoryAssignmentOrderOriginalInitialEnvironment();$auditFault->allowedCapability='other';$auditFault->throwAt='commit_attempt';$reads=0;try{$auditResult=AssignmentOrderOriginalVerificationFactory::create($auditFault->dependencies())->submitAssignmentOrderOriginal($command('00000000-0000-4000-8000-000000000240',AssignmentOrderOriginalMode::INITIAL,$stream($reads)));$auditThrown=null;}catch(Throwable$e){$auditThrown=$e;}assertSameValue(null,$auditThrown,'Attempt-audit Throwable is total.');assertSameValue([AssignmentOrderOriginalStatus::FAILED,AssignmentOrderOriginalReason::PERSISTENCE_FAILURE],[$auditResult->status(),$auditResult->reasonCode()],'Attempt-audit Throwable has exact failure.');assertSameValue(false,str_contains(json_encode([$rejected($auditResult),$auditFault->safeLogs],JSON_THROW_ON_ERROR),$auditFault->throwSecret),'Audit exception secret is absent.');

