$streamFault=new InMemoryAssignmentOrderOriginalInitialEnvironment();$closed=0;$throwingStream=new class($closed)implements AssignmentOrderOriginalByteStream{public function __construct(private int&$closed){}public function read(int$m):AssignmentOrderOriginalStreamRead{throw new RuntimeException('SECRET-STREAM-DETAIL');}public function close():void{$this->closed++;}};try{$streamResult=AssignmentOrderOriginalVerificationFactory::create($streamFault->dependencies())->submitAssignmentOrderOriginal($command('00000000-0000-4000-8000-000000000275',AssignmentOrderOriginalMode::INITIAL,$throwingStream));$streamThrown=null;}catch(Throwable$e){$streamThrown=$e;}assertSameValue(null,$streamThrown,'Stream Throwable is total.');assertSameValue([AssignmentOrderOriginalStatus::FAILED,AssignmentOrderOriginalReason::STREAM_FAILURE,true,1],[$streamResult->status(),$streamResult->reasonCode(),$streamResult->retryable(),$closed],'Stream Throwable maps exactly and closes once.');assertSameValue(false,str_contains(json_encode([$rejected($streamResult),$streamFault->safeLogs],JSON_THROW_ON_ERROR),'SECRET-STREAM-DETAIL'),'Stream secret does not leak.');

foreach(['lease_release','safe_log','delivery']as$index=>$phase){$post=new InMemoryAssignmentOrderOriginalInitialEnvironment();if($phase==='safe_log')$post->leaseReleaseFault='throw';$post->throwAt=$phase;$reads=0;try{$postResult=AssignmentOrderOriginalVerificationFactory::create($post->dependencies())->submitAssignmentOrderOriginal($command(sprintf('00000000-0000-4000-8000-%012d',280+$index),AssignmentOrderOriginalMode::INITIAL,$stream($reads)));$postThrown=null;}catch(Throwable$e){$postThrown=$e;}assertSameValue(null,$postThrown,'Post-commit observer Throwable does not escape at '.$phase);assertSameValue(AssignmentOrderOriginalStatus::ACCEPTED,$postResult->status(),'Committed fact remains accepted at '.$phase);assertSameValue(false,str_contains(json_encode([$rejected($postResult),$post->safeLogs],JSON_THROW_ON_ERROR),$post->throwSecret),'Post-commit secret absent at '.$phase);}

